import React from 'react';

const SkillBridgeLogo = ({ width = 82, height = 22.5, className = '' }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 520 110"
    width={width}
    height={height}
    preserveAspectRatio="xMinYMid meet"
    className={className}
    role="img"
    aria-label="SkillBridge AI"
  >
    <text
      x="0"
      y="90"
      fontFamily="'Plus Jakarta Sans', 'Inter', 'Helvetica Neue', Arial, sans-serif"
      fontWeight="700"
      fontSize="96"
      letterSpacing="-2"
    >
      <tspan fill="#181818">skillbridge</tspan>
      <tspan fill="#14A800">{' '}ai</tspan>
    </text>
  </svg>
);

export default SkillBridgeLogo;
